deltas.before:
// 登城马道：主墩台北面（宫内一侧）东西两端；顶面四周汉白玉栏杆
const top = PH + 0.3;
const sub = new THREE.Group();
sub.position.z = zc;
g.add(sub);
const asc = toWorld(buildGateAscent(this.library, sub, {
  W, D, topY: top, band: [D / 2 - 6, D / 2], edge: 'rail', railFacadeOnly: true,
}), new THREE.Matrix4().makeTranslation(this.ox, 0, this.oz + zc));
this.colliders.push(...asc.colliders);
this.walkables.push(...asc.walkables);

deltas.after:
// 午门专属三跑折返马道：官方平面支持拓扑；高度和配准为明确的模型拟合。
// 直接使用门局部原点，不沿用旧直坡子组的 zc 偏移。
const top = PH + 0.3;
const sub = new THREE.Group();
g.add(sub);
buildWumenAscent(this, sub);

import { getBuildingData } from './Layout.js';
import { WUMEN_ASCENT_PROFILE } from './palace/special/WumenAscentProfile.js';
import { fitWumenWallCap } from './palace/special/WumenWallCapFit.js';

const cap = buildWallCap(this.library, { length: len, thickness: t });
// Only the two Wumen return-flight junctions exclude their intersecting cap.
// Wall body, crenels, collider and distant cap paint registration stay intact.
if (wumenCapFit) fitWumenWallCap(cap, { length: len, ...wumenCapFit });
cap.position.set(cx, h, z);
